:root {
  --bg: #1e1e2f;
  --card: #2a2a40;
  --text: #e0e0e0;
  --accent: #6c5ce7;
  --accent-hover: #5a4bd1;
  --running: #00b894;
  --danger: #e17055;
  --border: #3a3a55;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, sans-serif;
  font-size: 16px;
  background: var(--bg);
  color: var(--text);
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 1rem;
}

.card {
  background: var(--card);
  border-radius: 12px;
  padding: 2rem;
  width: 100%;
  max-width: 480px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
}

h1 {
  font-size: 1.5rem;
  margin-bottom: 1.5rem;
  text-align: center;
  color: var(--accent);
}

.add-form {
  display: flex;
  gap: 0.5rem;
  margin-bottom: 1.5rem;
}

.add-form input {
  flex: 1;
  padding: 0.75rem 1rem;
  border: 2px solid var(--border);
  border-radius: 8px;
  background: var(--bg);
  color: var(--text);
  font-size: 1rem;
  outline: none;
  transition: border-color 0.2s;
}

.add-form input:focus {
  border-color: var(--accent);
}

.btn {
  padding: 0.75rem 1.25rem;
  border: none;
  border-radius: 8px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
  color: #fff;
}

.btn:active {
  transform: scale(0.96);
}

.btn.primary {
  background: var(--accent);
}

.btn.primary:hover {
  background: var(--accent-hover);
}

.btn.primary:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.task-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.task-item {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.75rem 1rem;
  background: var(--bg);
  border-radius: 8px;
  border: 2px solid transparent;
  transition: border-color 0.2s;
}

.task-item.running {
  border-color: var(--running);
}

.task-name {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-weight: 500;
}

.task-time {
  font-variant-numeric: tabular-nums;
  font-weight: 700;
  color: var(--accent);
  min-width: 3.5rem;
  text-align: right;
}

.task-item.running .task-time {
  color: var(--running);
}

.btn.small {
  padding: 0.4rem 0.75rem;
  font-size: 0.875rem;
}

.btn.start {
  background: var(--running);
}

.btn.start:hover {
  background: #00a383;
}

.btn.stop {
  background: var(--danger);
}

.btn.stop:hover {
  background: #c95a3e;
}

.btn.remove {
  background: transparent;
  color: var(--danger);
  border: 2px solid var(--danger);
}

.btn.remove:hover {
  background: var(--danger);
  color: #fff;
}

.btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.empty-state {
  text-align: center;
  color: #888;
  padding: 1rem 0;
}

.empty-state.hidden {
  display: none;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

@media (max-width: 400px) {
  .card {
    padding: 1.25rem;
  }
  .add-form {
    flex-direction: column;
  }
  .task-item {
    flex-wrap: wrap;
  }
  .task-name {
    flex-basis: 100%;
  }
  .task-time {
    text-align: left;
  }
}

const taskForm = document.getElementById('task-form');
const taskInput = document.getElementById('task-input');
const taskList = document.getElementById('task-list');
const emptyState = document.getElementById('empty-state');

let tasks = [];
let activeTaskId = null;
let intervalId = null;
let nextId = 1;

function formatTime(seconds) {
  const m = Math.floor(seconds / 60).toString().padStart(2, '0');
  const s = (seconds % 60).toString().padStart(2, '0');
  return `${m}:${s}`;
}

function render() {
  taskList.innerHTML = '';
  emptyState.classList.toggle('hidden', tasks.length > 0);

  tasks.forEach(task => {
    const li = document.createElement('li');
    li.className = 'task-item' + (task.id === activeTaskId ? ' running' : '');
    li.dataset.id = task.id;

    const nameSpan = document.createElement('span');
    nameSpan.className = 'task-name';
    nameSpan.textContent = task.name;

    const timeSpan = document.createElement('span');
    timeSpan.className = 'task-time';
    timeSpan.textContent = formatTime(task.elapsed);

    const toggleBtn = document.createElement('button');
    toggleBtn.className = 'btn small ' + (task.id === activeTaskId ? 'stop' : 'start');
    toggleBtn.textContent = task.id === activeTaskId ? 'Stop' : 'Start';
    toggleBtn.setAttribute('aria-pressed', task.id === activeTaskId);
    toggleBtn.setAttribute('aria-label', (task.id === activeTaskId ? 'Stop' : 'Start') + ' timer for ' + task.name);
    toggleBtn.addEventListener('click', () => toggleTask(task.id));

    const removeBtn = document.createElement('button');
    removeBtn.className = 'btn small remove';
    removeBtn.textContent = 'Remove';
    removeBtn.setAttribute('aria-label', 'Remove task ' + task.name);
    removeBtn.addEventListener('click', () => removeTask(task.id));

    li.append(nameSpan, timeSpan, toggleBtn, removeBtn);
    taskList.appendChild(li);
  });
}

function startTimer(taskId) {
  if (intervalId) {
    clearInterval(intervalId);
    intervalId = null;
  }
  activeTaskId = taskId;
  intervalId = setInterval(() => {
    const task = tasks.find(t => t.id === activeTaskId);
    if (task) {
      task.elapsed++;
      const timeEl = taskList.querySelector(`[data-id="${task.id}"] .task-time`);
      if (timeEl) timeEl.textContent = formatTime(task.elapsed);
    }
  }, 1000);
  render();
}

function stopTimer() {
  if (intervalId) {
    clearInterval(intervalId);
    intervalId = null;
  }
  activeTaskId = null;
  render();
}

function toggleTask(taskId) {
  if (activeTaskId === taskId) {
    stopTimer();
  } else {
    startTimer(taskId);
  }
}

function removeTask(taskId) {
  if (activeTaskId === taskId) {
    stopTimer();
  }
  tasks = tasks.filter(t => t.id !== taskId);
  render();
}

taskForm.addEventListener('submit', (e) => {
  e.preventDefault();
  const name = taskInput.value.trim();
  if (!name) return;
  tasks.push({ id: nextId++, name, elapsed: 0 });
  taskInput.value = '';
  taskInput.focus();
  render();
});

render();
